"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type LiquidRangeProps = {
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  className?: string;
  label?: string;
};

/**
 * Liquid-fill scrubber — the track blooms as you slide.
 */
function LiquidRange({
  value,
  defaultValue = 42,
  onValueChange,
  min = 0,
  max = 100,
  className,
  label = "Intensity",
}: LiquidRangeProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const current = value ?? internal;

  const set = (n: number) => {
    const next = Math.min(max, Math.max(min, n));
    if (value === undefined) setInternal(next);
    onValueChange?.(next);
  };

  const pct = ((current - min) / (max - min)) * 100;

  return (
    <div className={cn("w-full max-w-md space-y-2", className)}>
      <div className="flex items-center justify-between text-xs">
        <span className="font-medium text-muted-foreground">{label}</span>
        <span className="tabular-nums text-foreground">{Math.round(current)}</span>
      </div>
      <div className="relative h-12 overflow-hidden rounded-full border border-border bg-muted/50">
        <div
          className="absolute inset-y-0 left-0 rounded-full transition-[width] duration-75"
          style={{
            width: `${pct}%`,
            background:
              "linear-gradient(90deg, color-mix(in oklch, var(--color-primary) 55%, transparent), color-mix(in oklch, var(--color-chart-4) 70%, var(--color-primary)))",
            boxShadow:
              "0 0 24px color-mix(in oklch, var(--color-primary) 35%, transparent)",
          }}
        />
        <input
          type="range"
          min={min}
          max={max}
          value={current}
          onChange={(e) => set(Number(e.target.value))}
          className="absolute inset-0 z-[1] h-full w-full cursor-ew-resize opacity-0"
          aria-label={label}
        />
        <div
          aria-hidden
          className="pointer-events-none absolute top-1/2 size-8 -translate-y-1/2 rounded-full border border-border bg-card shadow-[var(--shadow-lift)] transition-[left] duration-75"
          style={{ left: `calc(${pct}% - 1rem)` }}
        />
      </div>
    </div>
  );
}

export { LiquidRange };
